//
// Prepend the regeneration note to `src/api/schema.d.ts` after
// `openapi-typescript` writes it.  Run by `pnpm gen:api-types`; the CI
// drift check regenerates the file and fails on any diff, so the
// header must be produced here rather than edited by hand.
//

import { readFileSync, writeFileSync } from "node:fs";

const path = process.argv[2];
const HEADER = `//
// GENERATED FILE -- do not edit.  TypeScript types for the mibudge REST
// API, generated by openapi-typescript from docs/openapi.yaml.
//
// Regenerate after the API changes:
//
//   make api-schema             # repo root: refresh docs/openapi.yaml
//   cd frontend && pnpm gen:api-types
//
// CI runs \`pnpm gen:api-types && git diff --exit-code src/api/schema.d.ts\`
// in the \`frontend lint\` step, so a stale copy fails the build.
// See docs/spa/api-and-models.md.
//
`;

const body = readFileSync(path, "utf8");
writeFileSync(path, body.startsWith(HEADER) ? body : HEADER + body);
